// Kai — Cool — generated by DAOS. Motion is Lottie; the sound is one mixed loop, played in sync.
import 'package:flutter/widgets.dart';
import 'package:daos_icons/daos_icons.dart';

class ChibiKaiCoolIcon extends StatelessWidget {
  const ChibiKaiCoolIcon({super.key, this.size = 64, this.autoplay = true, this.soundMode = DaosSoundMode.press});

  final double size;
  final bool autoplay;
  final DaosSoundMode soundMode;

  @override
  Widget build(BuildContext context) => DaosIcon(
        animation: 'lib/icons/chibi-kai-cool.lottie.json',
        sound: 'lib/icons/chibi-kai-cool.wav',
        duration: const Duration(milliseconds: 1800),
        stillFrame: const Duration(milliseconds: 600),
        label: 'Kai, the street skater in a backwards cap, dropping on sunglasses with a smirk',
        size: size,
        autoplay: autoplay,
        soundMode: soundMode,
      );
}
